    'ပဋိပက္ခ 1 (ရည်ရွယ်ချက်)\nဤမူဝါဒသည် (ရည်ရွယ်ချက်ကိုဖော်ပြသည်)။\n\nပဋိပက္ခ 2 (နယ်ပယ်)\n(1) (သက်ဆိုင်သူများသို့) အကျုံးဝင်သည်။\n(2) ခြွင်းချက်များကိုကား (အခြားမူဝါဒ)အရ ဆောင်ရွက်သည်။\n\nပဋိပက္ခ 3 (ဖေါ်ထုတ်ဖော်ပြချက်များ)\nဤစာတွင်သုံးစွဲသည့် ဝေါဟာရများသည် အောက်ပါအတိုင်း ဖြစ်သည်။',
